"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { MapContainer, TileLayer, GeoJSON, useMap } from "react-leaflet";
import type { Feature, FeatureCollection, Geometry } from "geojson";
import type { Layer, PathOptions, Map as LeafletMap, LatLngBounds } from "leaflet";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import { AnimatePresence, motion } from "framer-motion";

type DistrictProps = { [k: string]: unknown };

function normalizeName(s: string): string {
  return s
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/^okres\s+/, "")
    .trim();
}

function getDistrictNameRaw(f: Feature<Geometry, DistrictProps>): string {
  const props = (f.properties || {}) as Record<string, unknown>;
  const candidates = ["NM3", "name", "Name", "LAU_NAME", "DISTRICT", "District", "Okres", "okres", "NUTS_NAME"];
  for (const key of candidates) {
    const val = props[key];
    if (typeof val === "string" && val.trim()) return val;
  }
  for (const [, v] of Object.entries(props)) {
    if (typeof v === "string" && v.trim()) return v;
  }
  return "";
}

function SetupPanes() {
  const map = useMap();
  useEffect(() => {
    const ensure = (name: string, z: number) => {
      if (!map.getPane(name)) {
        map.createPane(name);
        const p = map.getPane(name);
        if (p) p.style.zIndex = String(z);
      }
    };

    ensure("west", 399);
    ensure("covered", 401);
    ensure("nodrone", 405);
  }, [map]);
  return null;
}

function MapAccess({ onMap }: { onMap: (map: LeafletMap) => void }) {
  const map = useMap();
  useEffect(() => {
    onMap(map);
  }, [map, onMap]);
  return null;
}

type DistrictKind = "covered" | "west" | "nodrone";

function kindLabel(k: DistrictKind) {
  if (k === "covered") return "Aktívne pokrytie";
  if (k === "west") return "Pokrytie v rámci možností";
  return "Bezdronové zóny";
}

export default function MapCoverage() {
  const [mounted, setMounted] = useState(false);

  const [westLayer, setWestLayer] = useState<FeatureCollection<Geometry, DistrictProps> | null>(null);
  const [coveredLayer, setCoveredLayer] = useState<FeatureCollection<Geometry, DistrictProps> | null>(null);
  const [noDroneLayer, setNoDroneLayer] = useState<FeatureCollection<Geometry, DistrictProps> | null>(null);
  const [bratislavaLayer, setBratislavaLayer] = useState<FeatureCollection<Geometry, DistrictProps> | null>(null);

  const [error, setError] = useState<string | null>(null);

  const [height, setHeight] = useState<number>(380);
  const [isMobile, setIsMobile] = useState(false);
  const [isLegendOpen, setIsLegendOpen] = useState(true);

  const [map, setMap] = useState<LeafletMap | null>(null);

  const [selected, setSelected] = useState<{ name: string; kind: DistrictKind } | null>(null);
  const selectedLayerRef = useRef<Layer | null>(null);
  const selectedKindRef = useRef<DistrictKind | null>(null);

  // responsive
  useEffect(() => {
    setMounted(true);

    const compute = () => {
      const w = window.innerWidth;
      setIsMobile(w < 640);

      if (w < 640) setHeight(380);
      else if (w < 1024) setHeight(500);
      else setHeight(600);
    };

    compute();
    window.addEventListener("resize", compute, { passive: true });
    return () => window.removeEventListener("resize", compute);
  }, []);

  useEffect(() => {
    setIsLegendOpen(!isMobile);
  }, [isMobile]);

  const coveredNames = useMemo(
    () =>
      [
        "Bánovce nad Bebravou",
        "Galanta",
        "Handlová",
        "Ilava",
        "Myjava",
        "Nitra",
        "Nové Mesto nad Váhom",
        "Piešťany",
        "Považská Bystrica",
        "Púchov",
        "Trenčín",
        "Šaľa",
      ].map(normalizeName),
    []
  );

  const westNames = useMemo(
    () =>
      [
        "Dunajská Streda",
        "Galanta",
        "Hlohovec",
        "Piešťany",
        "Senica",
        "Skalica",
        "Trnava",
        "Bánovce nad Bebravou",
        "Ilava",
        "Myjava",
        "Nové Mesto nad Váhom",
        "Partizánske",
        "Považská Bystrica",
        "Prievidza",
        "Púchov",
        "Trenčín",
        "Komárno",
        "Levice",
        "Nitra",
        "Nové Zámky",
        "Šaľa",
        "Topoľčany",
        "Zlaté Moravce",
        "Senec",
      ].map(normalizeName),
    []
  );

  // load districts
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch("/districts_epsg_4326.geojson", { cache: "no-store" });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = (await res.json()) as FeatureCollection<Geometry, DistrictProps>;

        const bratislavaNames = [
          "bratislava i",
          "bratislava ii",
          "bratislava iii",
          "bratislava iv",
          "bratislava v",
          "malacky",
          "pezinok",
        ];

        const west: FeatureCollection<Geometry, DistrictProps> = {
          type: "FeatureCollection",
          features: data.features.filter((f) => {
            const n = normalizeName(getDistrictNameRaw(f));
            const isBA = bratislavaNames.includes(n);
            return westNames.includes(n) && !isBA;
          }),
        };

        const covered: FeatureCollection<Geometry, DistrictProps> = {
          type: "FeatureCollection",
          features: data.features.filter((f) => coveredNames.includes(normalizeName(getDistrictNameRaw(f)))),
        };

        const bratislava: FeatureCollection<Geometry, DistrictProps> = {
          type: "FeatureCollection",
          features: data.features.filter((f) => bratislavaNames.includes(normalizeName(getDistrictNameRaw(f)))),
        };

        if (!cancelled) {
          setWestLayer(west);
          setCoveredLayer(covered);
          setBratislavaLayer(bratislava);
          setError(null);
        }
      } catch (e) {
        if (!cancelled) setError(e instanceof Error ? e.message : String(e));
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [westNames, coveredNames]);

  // load no-drone zones
  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const res = await fetch("/nodronezones.geojson", { cache: "no-store" });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);

        const data = (await res.json()) as FeatureCollection<Geometry, DistrictProps>;
        if (!cancelled) setNoDroneLayer(data);
      } catch (e) {
        if (!cancelled) setError((prev) => prev ?? (e instanceof Error ? e.message : String(e)));
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const styleWest: PathOptions = {
    color: "#9ca3af",
    weight: 1.2,
    opacity: 1,
    fillColor: "#9ca3af",
    fillOpacity: 0.25,
    stroke: true,
  };

  const styleCovered: PathOptions = {
    color: "#10b981",
    weight: 2,
    opacity: 1,
    fillColor: "#10b981",
    fillOpacity: 0.42,
    stroke: true,
  };

  const styleNoDrone: PathOptions = {
    color: "#ef4444",
    weight: 2,
    opacity: 1,
    fillColor: "#ef4444",
    fillOpacity: 0.32,
    stroke: true,
  };

  const hoverPatch: PathOptions = {
    weight: 3,
    fillOpacity: 0.55,
  };

  const selectedPatch: PathOptions = {
    weight: 4,
    fillOpacity: 0.62,
  };

  const applyStyle = (layer: Layer, style: PathOptions) => {
    (layer as L.Path).setStyle(style);
  };

  const baseStyleByKind = (k: DistrictKind): PathOptions =>
    k === "covered" ? styleCovered : k === "west" ? styleWest : styleNoDrone;

  const clearSelected = () => {
    if (selectedLayerRef.current && selectedKindRef.current) {
      applyStyle(selectedLayerRef.current, baseStyleByKind(selectedKindRef.current));
    }
    selectedLayerRef.current = null;
    selectedKindRef.current = null;
    setSelected(null);
  };

  const makeOnEachFeature =
    (kind: DistrictKind, base: PathOptions) =>
    (feature: Feature<Geometry, DistrictProps>, layer: Layer) => {
      const nameRaw = getDistrictNameRaw(feature);
      const name = nameRaw?.trim() ? nameRaw.trim() : "Neznámy okres";

      layer.on("mouseover", () => {
        if (selectedLayerRef.current === layer) return;
        applyStyle(layer, { ...base, ...hoverPatch });
      });

      layer.on("mouseout", () => {
        if (selectedLayerRef.current === layer) return;
        applyStyle(layer, base);
      });

      layer.on("click", () => {
        // clear old
        if (selectedLayerRef.current && selectedKindRef.current) {
          applyStyle(selectedLayerRef.current, baseStyleByKind(selectedKindRef.current));
        }

        selectedLayerRef.current = layer;
        selectedKindRef.current = kind;

        setSelected({ name, kind });
        applyStyle(layer, { ...base, ...selectedPatch });

        // fit bounds (no any)
        if (map) {
          const maybeBoundsLayer = layer as unknown as { getBounds?: () => LatLngBounds };
          const b = maybeBoundsLayer.getBounds?.();
          if (b && b.isValid()) {
            map.fitBounds(b.pad(0.25), { animate: true, duration: 0.5 });
          }
        }
      });
    };

  if (!mounted) return <div className="w-full h-[380px] rounded-2xl bg-white/5" />;

  return (
    <div className="relative rounded-2xl overflow-hidden ring-1 ring-white/10 bg-black/10">
      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.35 }}>
        <MapContainer
          center={[48.7, 19.7]}
          zoom={8}
          scrollWheelZoom={!isMobile}
          style={{ height: `${height}px`, width: "100%" }}
          className="touch-pan-x touch-pan-y"
        >
          <SetupPanes />
          <MapAccess onMap={setMap} />

          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution="&copy; OpenStreetMap contributors" noWrap />

          {westLayer && <GeoJSON data={westLayer} style={styleWest} pane="west" onEachFeature={makeOnEachFeature("west", styleWest)} />}
          {coveredLayer && (
            <GeoJSON data={coveredLayer} style={styleCovered} pane="covered" onEachFeature={makeOnEachFeature("covered", styleCovered)} />
          )}
          {bratislavaLayer && (
            <GeoJSON data={bratislavaLayer} style={styleNoDrone} pane="nodrone" onEachFeature={makeOnEachFeature("nodrone", styleNoDrone)} />
          )}
          {noDroneLayer && (
            <GeoJSON data={noDroneLayer} style={styleNoDrone} pane="nodrone" onEachFeature={makeOnEachFeature("nodrone", styleNoDrone)} />
          )}
        </MapContainer>
      </motion.div>

      {/* legend */}
      <div className="pointer-events-none absolute right-3 top-3 z-[500] flex flex-col items-end gap-2">
        {isMobile && (
          <button
            type="button"
            onClick={() => setIsLegendOpen((p) => !p)}
            className="pointer-events-auto rounded-full bg-black/70 ring-1 ring-white/20 backdrop-blur px-3 py-1.5 text-xs font-medium uppercase tracking-wide text-white/90 shadow-md shadow-black/40 hover:bg-black/80 transition"
            aria-expanded={isLegendOpen}
            aria-controls="map-legend"
          >
            Legenda
          </button>
        )}

        <AnimatePresence>
          {isLegendOpen && (
            <motion.div
              id="map-legend"
              className="pointer-events-auto mt-1 rounded-xl bg-black/60 ring-1 ring-white/15 text-white/90 backdrop-blur px-3.5 py-3 shadow-lg shadow-black/30"
              role="note"
              initial={{ opacity: 0, y: -6, scale: 0.985 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -5, scale: 0.99 }}
              transition={{ duration: 0.2 }}
            >
              <div className="text-xs uppercase tracking-wider text-white/60 mb-2">Legenda</div>
              <ul className="space-y-1.5 text-sm">
                <li className="flex items-center gap-2">
                  <span className="inline-block h-3 w-3 rounded-sm" style={{ background: "#10b981" }} />
                  <span>Aktívne pokrytie</span>
                </li>
                <li className="flex items-center gap-2">
                  <span className="inline-block h-3 w-3 rounded-sm" style={{ background: "#9ca3af" }} />
                  <span>Pokrytie v rámci možností</span>
                </li>
                <li className="flex items-center gap-2">
                  <span className="inline-block h-3 w-3 rounded-sm" style={{ background: "#ef4444" }} />
                  <span>Bezdronové zóny</span>
                </li>
              </ul>
              <div className="mt-3 text-xs text-white/55">Tip: Kliknite na okres pre detail.</div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* selected card */}
      <div className="pointer-events-none absolute left-3 bottom-3 z-[520] max-w-[92vw]">
        <AnimatePresence>
          {selected && (
            <motion.div
              className="pointer-events-auto rounded-2xl bg-black/65 backdrop-blur ring-1 ring-white/15 shadow-xl shadow-black/40 px-4 py-3"
              initial={{ opacity: 0, y: 14, scale: 0.99 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 10, scale: 0.995 }}
              transition={{ duration: 0.2 }}
            >
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="text-xs uppercase tracking-wider text-white/60">Vybraný okres</div>
                  <div className="text-base font-semibold text-white leading-tight">{selected.name}</div>
                  <div className="mt-1 text-sm text-white/80">{kindLabel(selected.kind)}</div>
                </div>
                <button
                  type="button"
                  onClick={clearSelected}
                  className="rounded-lg px-2 py-1 text-white/80 hover:text-white hover:bg-white/10 transition"
                  aria-label="Zrušiť výber"
                >
                  ✕
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {error && <div className="px-4 py-2 text-sm text-red-400 bg-red-400/10">Nepodarilo sa načítať mapové dáta: {error}</div>}
    </div>
  );
}
